mapper.sql:
where coalesce(d.deleted, 0) = 0

    and (
        d.device_code like concat('%', #{keyword}, '%')
        or d.device_name like concat('%', #{keyword}, '%')
    )


    and d.lab_id = #{labId}


    and coalesce(d.lab_name, l.lab_name) = #{labName}


    and d.category = #{category}


    and d.status = #{status}

mapper.select:
select



order by d.created_at desc, d.id desc
limit #{pageSize} offset #{offset}
